// inflection::Inflector::underscore(const std::string& in) -> std::string
// Operates on raw BYTES. No allocation limit, no truncation, no state.
// Pure: identical input always yields identical output; independent of
// initialize(), of argv position, and of any pluralization/irregular-word rules.

string underscore(string in):
    string out = ""                       // starts empty
    for i = 0 .. in.size()-1:             // i is the BYTE INDEX into the INPUT
        byte c = in[i]
        if (c >= 0x41 && c <= 0x5A):      // 'A'..'Z' ONLY (ASCII uppercase, "C" locale)
            if (i > 0):                   // <-- condition is on the INPUT INDEX, not on out.empty()
                out += '_'                // 0x5F
            out += (byte)(c + 0x20)       // tolower: 'A'->'a' ... 'Z'->'z'
        else:
            out += c                      // every other byte copied verbatim, unchanged
    return out

// Equivalent one-liner: for each byte, an ASCII A-Z becomes "_" + lowercase,
// except at byte index 0 where the leading "_" is omitted. Nothing else changes.
//
// NOT done by this function (all explicitly disproven):
//   - no collapsing / de-duplication of adjacent or pre-existing '_' bytes
//   - no acronym grouping (HTMLParser -> h_t_m_l_parser, one '_' per capital)
//   - no "::" -> "/" translation (Rails-style) ; "::" is passed through as-is
//   - no '-' -> '_' translation ; no whitespace -> '_' translation
//   - no trimming, no leading/trailing '_' cleanup
//   - no digit/word-boundary insertion ("Test99" -> "test99", "99Test" -> "99_test"
//     only because 'T' is uppercase)
//   - no UTF-8 awareness; multi-byte sequences are copied byte-for-byte and each
//     of their bytes still consumes an index (so a capital after them gets a '_')
